function pathPoly(points,fill,stroke=null){ctx.beginPath();ctx.moveTo(points[0][0],points[0][1]);for(let i=1;i<points.length;i++)ctx.lineTo(points[i][0],points[i][1]);ctx.closePath();ctx.fillStyle=fill;ctx.fill();if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=1;ctx.stroke()}}
function drawGround(camX,camY){ctx.fillStyle='#24342f';ctx.fillRect(0,0,W,H);let ox=(-camX)%96,oy=(-camY)%82;for(let x=ox-96;x<W+96;x+=96){for(let y=oy-82;y<H+82;y+=82){let wx=x+camX,wy=y+camY;let n=(Math.sin(wx*12.98+wy*3.1)*43758.5)%1;ctx.fillStyle=n>.2?'#283832':'#26362f';ctx.globalAlpha=.22;ctx.beginPath();ctx.ellipse(x+((wx*7)%29),y+((wy*11)%24),randStatic(wx+wy,8,24),randStatic(wx-wy,4,11),n,0,6.28);ctx.fill();ctx.globalAlpha=1}}let grad=ctx.createRadialGradient(W*.5,H*.48,60,W*.5,H*.5,Math.max(W,H)*.78);grad.addColorStop(0,'rgba(151,133,91,.15)');grad.addColorStop(.55,'rgba(81,94,67,.08)');grad.addColorStop(1,'rgba(4,11,12,.43)');ctx.fillStyle=grad;ctx.fillRect(0,0,W,H)}
function randStatic(a,min,max){let n=Math.sin(a*78.233)*43758.5453;n-=Math.floor(n);return min+n*(max-min)}
function drawDeco(d,cx,cy){let x=d.x-cx,y=d.y-cy;if(x<-100||x>W+100||y<-100||y>H+100)return;ctx.save();ctx.translate(x,y);ctx.rotate(d.rot);ctx.scale(d.s,d.s);if(d.type==='grass'){ctx.strokeStyle='#5e805e';ctx.globalAlpha=.45;ctx.lineWidth=1.5;for(let i=0;i<3;i++){ctx.beginPath();ctx.moveTo(0,5);ctx.quadraticCurveTo(randStatic(d.x+i, -5,5),-2,randStatic(d.y+i, -7,7),-randStatic(d.x*d.y+i,5,14));ctx.stroke()}}else if(d.type==='fern'){ctx.strokeStyle='#527b60';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(0,8);ctx.quadraticCurveTo(4,-2,0,-12);ctx.stroke();for(let i=0;i<4;i++){ctx.beginPath();ctx.ellipse(i%2?4:-4,-i*4,5,2,-.6,0,6.28);ctx.fillStyle=i%2?'#587b5e':'#688568';ctx.fill()}}else if(d.type==='stone'){ctx.shadowColor='#182321';ctx.shadowBlur=6;pathPoly([[-8,2],[-5,-5],[2,-7],[8,-1],[6,5],[-3,7]],'#52605a','#87908455');ctx.shadowBlur=0;ctx.strokeStyle='#a5a18a55';ctx.beginPath();ctx.moveTo(-2,-3);ctx.lineTo(1,-5);ctx.stroke()}else if(d.type==='pillar'){ctx.shadowColor='#080c0c';ctx.shadowBlur=9;ctx.fillStyle='#10191788';ctx.beginPath();ctx.ellipse(2,7,18,12,0,0,6.28);ctx.fill();pathPoly([[-12,-5],[-9,-21],[7,-23],[13,-13],[11,4],[-8,6]],'#5a6259','#acac9355');pathPoly([[-10,-18],[-7,-27],[9,-28],[12,-20]],'#8b8b73','#c9bd9860');ctx.fillStyle='#373f39';ctx.fillRect(-6,-18,3,14);ctx.fillRect(4,-20,2,17);ctx.shadowBlur=0}else if(d.type==='tree'){ctx.shadowColor='#0b1311';ctx.shadowBlur=12;ctx.fillStyle='#131c18';ctx.beginPath();ctx.ellipse(4,9,24,16,0,0,6.28);ctx.fill();ctx.fillStyle='#304238';ctx.beginPath();ctx.arc(0,-7,20,0,6.28);ctx.fill();ctx.fillStyle='#3d5143';ctx.beginPath();ctx.arc(-7,-12,12,0,6.28);ctx.fill();ctx.fillStyle='#566047';ctx.beginPath();ctx.arc(7,-14,8,0,6.28);ctx.fill();ctx.fillStyle='#75805b';ctx.globalAlpha=.45;ctx.beginPath();ctx.arc(-5,-17,4,0,6.28);ctx.fill();ctx.shadowBlur=0}ctx.restore()}
function drawGroundMarks(cx,cy){let x=1100-cx,y=820-cy;ctx.save();ctx.translate(x,y);ctx.strokeStyle='#c2a87617';ctx.lineWidth=2;for(let r=1;r<5;r++){ctx.beginPath();ctx.ellipse(0,0,95+r*27,62+r*20,-.08,0,6.28);ctx.stroke()}ctx.strokeStyle='#d5bc803c';ctx.lineWidth=2;for(let i=0;i<8;i++){let a=i*6.28/8;ctx.beginPath();ctx.moveTo(Math.cos(a)*125,Math.sin(a)*87);ctx.lineTo(Math.cos(a)*180,Math.sin(a)*132);ctx.stroke()}ctx.restore()}
function drawShadow(x,y,r,alpha=.3){ctx.fillStyle=`rgba(4,9,8,${alpha})`;ctx.beginPath();ctx.ellipse(x,y+r*.65,r*1.25,r*.55,0,0,6.28);ctx.fill()}
function drawActor(x,y,dir,r,color,glow,phase=0,isPlayer=false){drawShadow(x,y,r,.38);ctx.save();ctx.translate(x,y);let bob=Math.sin(phase*6)*1.5;ctx.translate(0,bob);if(glow){ctx.shadowColor=glow;ctx.shadowBlur=isPlayer?20:14}if(isPlayer){ctx.rotate(dir);ctx.fillStyle='#233533';ctx.beginPath();ctx.ellipse(-3,4,9,14,-.2,0,6.28);ctx.fill();ctx.fillStyle='#53716a';ctx.beginPath();ctx.ellipse(-1,1,7,11,0,0,6.28);ctx.fill();ctx.fillStyle='#decaa0';ctx.beginPath();ctx.arc(4,-2,5.5,0,6.28);ctx.fill();ctx.fillStyle='#9e473e';ctx.beginPath();ctx.moveTo(-8,-8);ctx.lineTo(-2,-16);ctx.lineTo(6,-7);ctx.lineTo(3,-4);ctx.closePath();ctx.fill();ctx.strokeStyle='#d9e3ce';ctx.lineWidth=2.4;ctx.beginPath();ctx.moveTo(4,3);ctx.lineTo(14,3);ctx.stroke();ctx.strokeStyle='#be9b63';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(4,3);ctx.lineTo(0,3);ctx.stroke()}else{ctx.fillStyle=color;ctx.beginPath();ctx.ellipse(0,0,r*.8,r*(.72+Math.sin(phase*4)*.06),0,0,6.28);ctx.fill();ctx.fillStyle='#d8ead3';ctx.globalAlpha=.9;ctx.beginPath();ctx.arc(-4,-2,2,0,6.28);ctx.arc(4,-2,2,0,6.28);ctx.fill();ctx.globalAlpha=1;ctx.strokeStyle='#d8ead344';ctx.lineWidth=1;ctx.beginPath();ctx.arc(0,1,r*.48,.25,2.9);ctx.stroke()}ctx.restore()}
function draw(){ctx.setTransform(dpr,0,0,dpr,0,0);let zoom=Math.min(1.13,Math.max(.82,Math.min(W/900,H/570)));let vw=W/zoom,vh=H/zoom;let camX=clamp(player.x-vw/2,0,world.w-vw),camY=clamp(player.y-vh/2,0,world.h-vh);ctx.save();if(shake>0)ctx.translate(rand(-shake,shake),rand(-shake,shake));ctx.scale(zoom,zoom);ctx.translate(-camX,-camY);drawGround(camX,camY);drawGroundMarks(camX,camY);decor.forEach(d=>drawDeco(d,0,0));
// moonlit pools and scattered embers
for(let i=0;i<7;i++){let x=500+i*273,y=320+((i*271)%950);let g=ctx.createRadialGradient(x,y,2,x,y,75);g.addColorStop(0,'#83b29a0b');g.addColorStop(1,'#83b29a00');ctx.fillStyle=g;ctx.beginPath();ctx.arc(x,y,75,0,6.28);ctx.fill()}
for(let p of particles){ctx.globalAlpha=clamp(p.life/p.max,0,1);if(p.kind==='orb'){ctx.shadowColor=p.color;ctx.shadowBlur=18;ctx.fillStyle=p.color;ctx.beginPath();ctx.arc(p.x,p.y,p.size,0,6.28);ctx.fill();ctx.shadowBlur=0}else{ctx.fillStyle=p.color;ctx.beginPath();ctx.arc(p.x,p.y,p.size*clamp(p.life/p.max,0,1),0,6.28);ctx.fill()}}ctx.globalAlpha=1;
for(let e of enemies){let col=e.type==='wraith'?'#7899a0':e.type==='brute'?'#816b62':'#6e997e';drawActor(e.x,e.y,e.dir,e.r,e.flash?'#fff':col,e.type==='wraith'?'#a2e8ec':e.type==='brute'?'#bc8265':'#88d5a5',e.phase);let w=e.r*2.2;ctx.fillStyle='#141d1b';ctx.fillRect(e.x-w/2,e.y-e.r-12,w,3);ctx.fillStyle='#d88e74';ctx.fillRect(e.x-w/2,e.y-e.r-12,w*e.hp/e.maxHp,3)}
if(boss){drawShadow(boss.x,boss.y,boss.r,.55);ctx.save();ctx.translate(boss.x,boss.y);ctx.rotate(Math.sin(boss.phase)*.1);ctx.shadowColor='#ed795e';ctx.shadowBlur=30;ctx.fillStyle=boss.flash?'#fff':'#583f3b';ctx.beginPath();ctx.moveTo(-30,20);ctx.lineTo(-26,-13);ctx.lineTo(-15,-34);ctx.lineTo(-4,-23);ctx.lineTo(9,-39);ctx.lineTo(23,-17);ctx.lineTo(30,18);ctx.lineTo(17,29);ctx.lineTo(-19,29);ctx.closePath();ctx.fill();ctx.fillStyle='#df9470';ctx.beginPath();ctx.arc(-9,-7,3,0,6.28);ctx.arc(10,-7,3,0,6.28);ctx.fill();ctx.shadowBlur=0;ctx.restore()}
let visiblePlayer=player.inv<=0||Math.floor(time*18)%2===0;if(visiblePlayer){if(player.attack>0){ctx.save();ctx.translate(player.x,player.y);ctx.rotate(player.dir);ctx.strokeStyle=`rgba(229,236,211,${player.attack/.36*.7})`;ctx.lineWidth=5;ctx.beginPath();ctx.arc(0,0,54,-.85,.85);ctx.stroke();ctx.strokeStyle='#edcf8e';ctx.lineWidth=2;ctx.beginPath();ctx.arc(0,0,59,-.82,.82);ctx.stroke();ctx.restore()}drawActor(player.x,player.y,player.dir,player.r,'#53716a','#70d4bf',time,true)}
ctx.restore();ctx.restore();requestAnimationFrame(draw)}requestAnimationFrame(draw);

