function burst(x,y,color,n=8,power=100){for(let i=0;i<n;i++){let a=rand(0,6.28),s=rand(power*.25,power);particles.push({x,y,vx:Math.cos(a)*s,vy:Math.sin(a)*s,life:rand(.28,.65),max:.65,color,size:rand(2,5),kind:'spark'})}}
function attack(){if(gameover||paused||player.attack>0)return;player.attack=.36;let targets=boss?[boss,...enemies]:enemies;for(let e of targets){let dx=e.x-player.x,dy=e.y-player.y,d=Math.hypot(dx,dy),delta=Math.atan2(Math.sin(Math.atan2(dy,dx)-player.dir),Math.cos(Math.atan2(dy,dx)-player.dir));if(d<88+e.r&&Math.abs(delta)<1.12){e.hp-=24+player.level*5;e.flash=.15;burst(e.x,e.y,e===boss?'#e98b68':'#bde6c4',7,125);shake=4;if(e.hp<=0){if(e===boss){boss=null;document.getElementById('bossbar').classList.remove('show');gameover=true;document.getElementById('modalTitle').textContent='The ember endures.';document.getElementById('modalText').textContent='The Warden has fallen. The restless shades are gone, and the valley can breathe again.';document.getElementById('restart').textContent='Play again';document.getElementById('overlay').classList.add('show')}else{enemies.splice(enemies.indexOf(e),1);player.kills++;player.xp+=35;burst(e.x,e.y,'#bde6c4',14,150);if(Math.random()<.2&&player.potions<5){player.potions++;toast('POTION FOUND',`${player.potions} carried`)}while(player.xp>=player.level*100){player.xp-=player.level*100;player.level++;player.maxHp+=12;player.hp=Math.min(player.maxHp,player.hp+35);toast('LEVEL UP',`Level ${player.level} · vitality restored`)}}break}}updateHud()}
function dodge(){if(gameover||player.dashCd>0)return;player.dash=.2;player.dashCd=.85;player.inv=.32;let x=(keys.d?1:0)-(keys.a?1:0),y=(keys.s?1:0)-(keys.w?1:0);if(x||y)player.dir=Math.atan2(y,x);burst(player.x,player.y,'#8bdac8',7,75)}function potion(){if(player.potions<=0||player.hp>=player.maxHp||gameover)return;player.potions--;player.hp=Math.min(player.maxHp,player.hp+45);burst(player.x,player.y,'#e88d85',12,85);toast('EMBER TONIC','Vitality restored');updateHud()}
function endRun(won){gameover=true;document.getElementById('modalTitle').textContent=won?'The ember endures.':'The light fades…';document.getElementById('modalText').textContent=won?'The Warden has fallen. The valley can breathe again.':`You fought bravely, striking down ${player.kills} shades. The valley still waits for its champion.`;document.getElementById('restart').textContent='Rise again';document.getElementById('overlay').classList.add('show')}
function update(dt){time+=dt;if(toastTimer>0&&(toastTimer-=dt)<=0)document.getElementById('toast').classList.remove('show');if(gameover||paused)return;player.attack=Math.max(0,player.attack-dt);player.dash=Math.max(0,player.dash-dt);player.dashCd=Math.max(0,player.dashCd-dt);player.inv=Math.max(0,player.inv-dt);shake=Math.max(0,shake-dt*18);let ax=(keys.d?1:0)-(keys.a?1:0),ay=(keys.s?1:0)-(keys.w?1:0);if(ax||ay){let l=Math.hypot(ax,ay);ax/=l;ay/=l;player.dir=Math.atan2(ay,ax)}let speed=player.speed*(player.dash?3.5:1);player.x=clamp(player.x+ax*speed*dt,35,world.w-35);player.y=clamp(player.y+ay*speed*dt,35,world.h-35);spawnTimer-=dt;if(spawnTimer<=0){for(let i=0;i<Math.min(3+Math.floor(time/28),8);i++)spawnEnemy(Math.random()<.23?'wraith':Math.random()<.3?'brute':'shade');spawnTimer=Math.max(1.65,4.2-time*.015)}
for(let e of enemies){e.phase+=dt*2;e.flash=Math.max(0,e.flash-dt);let dx=player.x-e.x,dy=player.y-e.y,d=Math.hypot(dx,dy)||1;if(d>e.r+player.r+4){e.x+=dx/d*e.speed*dt;e.y+=dy/d*e.speed*dt}e.attack-=dt;if(d<e.r+player.r+8&&e.attack<=0){e.attack=e.type==='wraith'?1.1:1.4;if(player.inv<=0){player.hp-=e.type==='brute'?15:10;player.inv=.55;shake=8;burst(player.x,player.y,'#ee8273',7,100);if(player.hp<=0){player.hp=0;endRun(false)}}}}
if(boss){boss.phase+=dt;boss.flash=Math.max(0,boss.flash-dt);let dx=player.x-boss.x,dy=player.y-boss.y,d=Math.hypot(dx,dy)||1;if(d>boss.r+player.r+16){boss.x+=dx/d*boss.speed*dt;boss.y+=dy/d*boss.speed*dt}boss.attack-=dt;if(boss.attack<=0&&d<270){boss.attack=2.4;for(let i=0;i<8;i++){let a=i*Math.PI/4;particles.push({x:boss.x,y:boss.y,vx:Math.cos(a)*150,vy:Math.sin(a)*150,life:1.1,max:1.1,color:'#e97862',size:7,kind:'orb'})}}if(d<boss.r+player.r+10&&boss.attack<.3&&player.inv<=0){player.hp-=22;player.inv=.65;shake=10;if(player.hp<=0)endRun(false)}}
for(let i=particles.length-1;i>=0;i--){let p=particles[i];p.x+=p.vx*dt;p.y+=p.vy*dt;p.vx*=Math.pow(.1,dt);p.vy*=Math.pow(.1,dt);p.life-=dt;if(p.kind==='orb'&&Math.hypot(p.x-player.x,p.y-player.y)<player.r+8&&player.inv<=0){player.hp-=12;player.inv=.45;p.life=0;shake=7;if(player.hp<=0)endRun(false)}if(p.life<=0)particles.splice(i,1)}updateHud()}

